//! Built-in demo HAR 1.2 session for zero-setup onboarding exploration.
//!
//! Lets new users inspect JSON/GraphQL/HTML/form bodies, JWT/Cookie annotations,
//! timing breakdowns, slow-request warnings, error repair buttons (C1),
//! domain facets, and sequence diagrams before configuring a proxy.

use std::time::{Duration, SystemTime, UNIX_EPOCH};

use serde_json::{Value, json};

/// Number of demo flows generated by [`sample_har_document`].
#[cfg(test)]
pub const SAMPLE_FLOW_COUNT: usize = 7;

/// Builds a fresh HAR 1.2 document with timestamps anchored near `crate::clock::now()`.
pub fn sample_har_document() -> Value {
    let now = crate::clock::now();
    sample_har_at(now)
}

