struct Timings {
    dns: i64,
    connect: i64,
    ssl: i64,
    wait: i64,
    receive: i64,
}

struct EntrySpec<'a> {
    started: SystemTime,
    method: &'a str,
    url: &'a str,
    http_version: &'a str,
    status: u16,
    status_text: &'a str,
    req_headers: &'a [(&'a str, &'a str)],
    req_mime: Option<&'a str>,
    req_body: &'a str,
    res_headers: &'a [(&'a str, &'a str)],
    res_mime: &'a str,
    res_body: &'a str,
    timings: Timings,
    server_ip: &'a str,
    comment: &'a str,
}

fn har_entry(spec: EntrySpec<'_>) -> Value {
    let total = spec.timings.dns.max(0)
        + spec.timings.connect.max(0)
        + spec.timings.ssl.max(0)
        + spec.timings.wait.max(0)
        + spec.timings.receive.max(0);
    let mut request = json!({
        "method": spec.method,
        "url": spec.url,
        "httpVersion": spec.http_version,
        "headers": headers_json(spec.req_headers),
        "queryString": [],
        "headersSize": -1,
        "bodySize": spec.req_body.len() as i64,
    });
    if let Some(mime) = spec.req_mime {
        request["postData"] = json!({
            "mimeType": mime,
            "text": spec.req_body,
        });
    }
    json!({
        "startedDateTime": format_iso_utc(spec.started),
        "time": total,
        "serverIPAddress": spec.server_ip,
        "comment": spec.comment,
        "request": request,
        "response": {
            "status": spec.status,
            "statusText": spec.status_text,
            "httpVersion": spec.http_version,
            "headers": headers_json(spec.res_headers),
            "content": {
                "size": spec.res_body.len(),
                "mimeType": spec.res_mime,
                "text": spec.res_body,
            },
            "headersSize": -1,
            "bodySize": spec.res_body.len() as i64,
        },
        "cache": {},
        "timings": {
            "blocked": -1,
            "dns": spec.timings.dns,
            "connect": spec.timings.connect,
            "ssl": spec.timings.ssl,
            "send": 0,
            "wait": spec.timings.wait,
            "receive": spec.timings.receive,
        },
    })
}

fn headers_json(headers: &[(&str, &str)]) -> Vec<Value> {
    headers
        .iter()
        .map(|(name, value)| json!({"name": name, "value": value}))
        .collect()
}

fn offset_before(now: SystemTime, millis: u64) -> SystemTime {
    now.checked_sub(Duration::from_millis(millis))
        .unwrap_or(UNIX_EPOCH)
}

/// Formats a `SystemTime` as `YYYY-MM-DDTHH:MM:SS.mmmZ` without external date crates.
fn format_iso_utc(at: SystemTime) -> String {
    let dur = at.duration_since(UNIX_EPOCH).unwrap_or_default();
    let total_secs = dur.as_secs();
    let millis = dur.subsec_millis();
    let days = (total_secs / 86_400) as i64;
    let rem = total_secs % 86_400;
    let hour = rem / 3600;
    let min = (rem % 3600) / 60;
    let sec = rem % 60;
    let (year, month, day) = civil_from_days(days);
    format!("{year:04}-{month:02}-{day:02}T{hour:02}:{min:02}:{sec:02}.{millis:03}Z")
}

/// Howard Hinnant's civil-from-days algorithm (days since 1970-01-01).
fn civil_from_days(days_since_epoch: i64) -> (i64, u32, u32) {
    let z = days_since_epoch + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146_096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = y + i64::from(m <= 2);
    (year, m as u32, d as u32)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sample_har_document_has_expected_entries_and_valid_iso_timestamps() {
        let doc = sample_har_at(UNIX_EPOCH + Duration::from_secs(1_735_689_600));
        let entries = doc["log"]["entries"].as_array().expect("HAR entries array");
        assert_eq!(entries.len(), SAMPLE_FLOW_COUNT);
        assert_eq!(
            entries[0]["startedDateTime"].as_str(),
            Some("2024-12-31T23:59:46.000Z")
        );
    }

    #[cfg(not(target_arch = "wasm32"))]
    #[test]
    fn sample_har_imports_cleanly_with_diverse_flows() {
        let doc = sample_har_document();
        let imported = crate::har::import_har(&doc);
        assert_eq!(imported.len(), SAMPLE_FLOW_COUNT);

        // Verify 2xx, 4xx, 5xx, and ERR (status None + error) are all represented,
        // and normal HTTP status flows never carry bogus `statusText` errors like `"OK"`.
        assert!(imported.iter().any(|f| f.status == Some(200)));
        assert!(imported.iter().any(|f| f.status == Some(401)));
        assert!(imported.iter().any(|f| f.status == Some(502)));
        for flow in imported.iter().filter(|f| f.status.is_some()) {
            assert_eq!(
                flow.error, None,
                "normal HTTP response {} {} should not populate Flow::error",
                flow.method, flow.path
            );
        }
        let tls_err = imported
            .iter()
            .find(|f| f.status.is_none() && f.error.as_deref().unwrap_or("").contains("证书被拒绝"))
            .expect("TLS pinning ERR sample flow");
        assert_eq!(
            crate::ui::classify_error(tls_err.status, tls_err.error.as_deref().unwrap_or("")),
            Some(crate::ui::ErrorCategory::TlsTrust)
        );
        assert!(
            !crate::ui::actions_for_error(
                tls_err.status,
                tls_err.error.as_deref().unwrap_or(""),
                &tls_err.host,
                true,
            )
            .is_empty()
        );
        assert!(
            !crate::ui::actions_for_error(
                tls_err.status,
                tls_err.error.as_deref().unwrap_or(""),
                &tls_err.host,
                false,
            )
            .is_empty()
        );

        // Verify slow flow (>= 1s) exists.
        assert!(imported.iter().any(|f| {
            f.finished_at
                .and_then(|end| end.duration_since(f.started).ok())
                .is_some_and(|dur| dur >= Duration::from_secs(1))
        }));

        // Verify GraphQL flow exists.
        assert!(imported.iter().any(|f| {
            crate::present::graphql_operation_label(&f.path, &f.request_body).as_deref()
                == Some("GetCheckoutSummary")
        }));
    }
}
